pou.body:
{ST_IMPLEMENTATION}
	{implicit on}
	{p 3}WHILE(pstrHelpYear[0] <> BYTE#0 AND pstrHelpYear[0] <> BYTE#16#2D (*'-'*)) DO
{p 4}  pstrHelpYear := pstrHelpYear + 1;
{p 5}END_WHILE      
{p 11}
{p 12}i := DWORD_TO_DINT(pstrHelpYear - pstr);
{p 13}
{p 14}IF (i = 4) THEN
