{p 16}ELSE
{p 17}	RETURN;
{p 18}END_IF
{p 19}
{p 20}pstrHelpYear := pstrHelpYear + 1;
{p 21}pstrHelpMonth := pstrHelpYear;
{p 22}WHILE(pstrHelpMonth[0] <> BYTE#16#2d (*'-'*)) DO
{p 23}	pstrHelpMonth := pstrHelpMonth+1;
{p 24}END_WHILE
{p 25}i := DWORD_TO_DINT(pstrHelpMonth - pstrHelpYear);
{p 26}IF (i = 1 OR i = 2) THEN
{p 27}	nMonth := __HelpConvertString(pstrHelpYear,DINT_TO_UDINT(i));
{p 28}ELSE
{p 29}	RETURN;
{p 30}END_IF
{p 31}
{p 32}pstrHelpMonth := pstrHelpMonth+1;
