{p 34}WHILE(pstrHelpDay[0] <> 0 AND pstrHelpDay[0] <> BYTE#16#2d (*'-'*)) DO
{p 35}	pstrHelpDay := pstrHelpDay + 1;
{p 36}END_WHILE
{p 37}
{p 38}i := DWORD_TO_DINT(pstrHelpDay - pstrHelpMonth);
{p 39}IF (i = 1 OR i = 2) THEN
{p 40}	nDay := __HelpConvertString(pstrHelpMonth,DINT_TO_UDINT(i));
{p 41}ELSE 
{p 42}	RETURN;
{p 43}END_IF
{p 44}
{p 45}ppstr^ := pstrHelpDay;
{p 46}
{p 174}n400 := nYear / 400;
{p 181}n100 := nYear / 100;
{p 182}n4 := nYear / 4;
{p 238}
{p 184}// leap days till calculated date
{p 186}nLeapDays := n400 + n4 - n100;
{p 239}
{p 231}// correct for dates before march
{p 230}IF (__IsLeapYear(nYear) AND nMonth < 3) THEN
{p 232}	nLeapDays := nLeapDays - 1;
{p 233}END_IF
{p 235}
{p 234}nLeapDays := ABS(LEAPDAYSTILL1970 - nLeapDays);
{p 236}
{p 130}nDiffYear := nYear - 1970;
{p 151}
{p 150}IF nDiffYear < 0 THEN
{p 152}	nDays := (-1-nDiffYear) * 365 + nLeapDays;
{p 160}	FOR i := 11 TO nMonth BY - 1 DO
{p 161}		nDays := nDays + DayOfMonthTable[i];
{p 162}	END_FOR
{p 163}	nDays := nDays + DayOfMonthTable[nMonth-1] - nDay + 1;
{p 155}ELSE
{p 156}	nDays := nDiffYear * 365 + nLeapDays;  
{p 157}	FOR i := 0 TO nMonth - 2 DO
{p 158}		nDays := nDays + DayOfMonthTable[i];
{p 159}	END_FOR
{p 164}	nDays := nDays + nDay-1;
{p 153}END_IF
{p 149} 
{p 111}// convert to nanoseconds
{p 70}ulTime := nDays * NSPERDAY;
{p 165}IF (nDiffYear < 0) THEN
{p 166}	ulTime := 0 - ulTime;
{p 167}END_IF
