pou.body:
{ST_IMPLEMENTATION}
	{implicit on}
{p 213}// input is in days from 1970 positive or negative
	__GetYearAndDays(nDays := nDays, nYear => nYear);
{p 272}
{p 239}IF __IsLeapYear(nYear) THEN
{p 238}	DayOfMonthTable[1] := 29;
{p 269}ELSE
{p 270}	DayOfMonthTable[1] := 28;
{p 241}END_IF
{p 271}
{p 178}
{p 179}WHILE (nDays >= DayOfMonthTable[nMonth]) DO
{p 180}	nDays := nDays - DayOfMonthTable[nMonth];
{p 181}	nMonth := nMonth + 1;
{p 182}END_WHILE
{p 183}
{p 184}nMonth := nMonth + 1;
{p 185}nDay := nDays + 1;  (* nYear, nMonth, nDay are complete *)
{p 186}__HelpConvert(TO_DWORD(nYear), ADR(pstr),4);
{p 187}pstr[0] := BYTE#16#2d; (*'-'*)
{p 188}pstr := pstr + 1;
{p 189}__HelpConvert(TO_DWORD(nMonth),ADR(pstr), 2);
{p 190}pstr[0] := BYTE#16#2d; (*'-'*)
{p 191}pstr := pstr + 1;
{p 192}__HelpConvert(TO_DWORD(nDay),ADR(pstr), 2);
{p 193}ppstr^ := pstr;
