pou.body:
{ST_IMPLEMENTATION}
		{implicit on}
		{p 22}nDaysFrom1 := DAYSTO1970 + nDays;
		{p 23}
		{p 24}y400 := nDaysFrom1 / DAYSTO400;
		{p 25}nDaysFrom1 := nDaysFrom1 - (y400 * DAYSTO400);
		{p 26}y100 := nDaysFrom1 / DAYSTO100;
		{p 27}IF (y100 = 4) THEN// The last 100-year is divisble by 400, a leap year. So we have to adjust here.
		{p 28}    y100 := 3;
		{p 29}END_IF
		{p 30}nDaysFrom1 := nDaysFrom1 - y100 * DAYSTO100;
		{p 31}y4 := nDaysFrom1 / DAYSTO4;
		{p 32}nDaysFrom1 := nDaysFrom1 - y4 * DAYSTO4;
		{p 33}y1 := nDaysFrom1 / DAYSTO1;
		{p 34}IF (y1 = 4) THEN
		{p 35}	y1 := 3;
		{p 36}END_IF
		{p 37}nDays := nDaysFrom1 - y1 * DAYSTO1;
		{p 38}nYear := y400 * 400 + y100 * 100 + y4 * 4 + y1 + 1;
		{p 21}

